// 独立复验第 3 段：codex 会话的 running→done 迁移与 claude 一样触发联动（零特判）
const fs = require('fs'), os = require('os'), path = require('path'), cp = require('child_process');
const REPO = '/Users/shunyu/projects/pet-agent-status';
let fails = 0;
const ck = (n, c, e) => { console.log((c ? 'ok   ' : 'FAIL ') + n + (c ? '' : ' :: ' + e)); if (!c) fails++; };

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'us006lk-'));
const env = Object.assign({}, process.env, { PET_AGENT_STATUS_DIR: dir });
const hook = (fx) => cp.spawnSync(process.execPath, [path.join(REPO, 'hooks/codex-status-hook.js')],
  { input: fs.readFileSync(path.join(REPO, 'fixtures/codex-events', fx)), env });

const { readSnapshots } = require(path.join(REPO, 'lib/state-files.js'));
const { aggregate } = require(path.join(REPO, 'lib/aggregate.js'));
const { createPetLink, HOST_ANIM_STATES, DONE_ANIM } = require(path.join(REPO, 'lib/pet-link.js'));

const link = createPetLink();
const calls = [];
const pet = { pet: { playAnim: (n) => calls.push(['playAnim', n]), bubble: (m) => calls.push(['bubble', m]) } };
const snapRows = () => { const s = readSnapshots(dir); const now = Math.max(...s.records.map(r => r.ts)) + 1000; return { rows: aggregate(s, { now, isPidAlive: () => true }).rows, now }; };

// 轮 1：SessionStart → running（首见，不该喊）
hook('session-start.json');
let a = snapRows();
let f1 = link.onSnapshot(a.rows, pet, { now: a.now, t: (k, v) => k + ':' + (v && v.project) });
ck('轮1 running 首见不触发联动', f1.length === 0, JSON.stringify(f1));

// 轮 2：Stop → done（running→done 真迁移）
hook('stop.json');
let b = snapRows();
const cxRow = b.rows.find(r => r.agent === 'codex');
ck('codex 行 raw=done / state=idle', cxRow && cxRow.raw === 'done' && cxRow.state === 'idle', JSON.stringify(cxRow));
let f2 = link.onSnapshot(b.rows, pet, { now: b.now, t: (k, v) => k + ':' + (v && v.project) });
const anims = calls.filter(c => c[0] === 'playAnim').map(c => c[1]);
const bubbles = calls.filter(c => c[0] === 'bubble').map(c => c[1]);
ck('轮2 codex running→done 触发 playAnim', anims.length === 1, JSON.stringify(calls));
ck('playAnim 实际传参在宿主合法集合内', anims.every(x => HOST_ANIM_STATES.includes(x)), JSON.stringify(anims));
ck('playAnim 传参 = DONE_ANIM(unread)', anims[0] === DONE_ANIM && DONE_ANIM === 'unread', String(anims[0]));
ck('轮2 也发了 bubble', bubbles.length === 1, JSON.stringify(bubbles));
ck('bubble 文案带项目名（走同一 t 路径）', /bubble\.done:/.test(bubbles[0] || ''), String(bubbles[0]));
ck('fired 记录 sessionId 为 codex 会话', f2.every(x => x.sessionId === '01a08ab6-557f-77b3-bc37-3553f712b2e0'), JSON.stringify(f2));

// 反证：把 raw 改成非 done，确认断言载重（不是恒真）
const link2 = createPetLink(); const calls2 = [];
const pet2 = { pet: { playAnim: (n) => calls2.push(n), bubble: () => {} } };
link2.onSnapshot(a.rows, pet2, { now: a.now, t: (k) => k });
const mutated = b.rows.map(r => Object.assign({}, r, { raw: 'running' }));
link2.onSnapshot(mutated, pet2, { now: b.now, t: (k) => k });
ck('反证：raw 改成 running 后 playAnim 不再触发（断言非恒真）', calls2.length === 0, JSON.stringify(calls2));

fs.rmSync(dir, { recursive: true, force: true });
console.log(fails === 0 ? '\nLINK: ALL PASS' : '\nLINK: ' + fails + ' FAILED');
process.exit(fails ? 1 : 0);

