'use strict';
// 独立复验第 4 段：panel 里 Codex 是真按钮（到期契约已翻面）+ codex 行徽标数据驱动
const fs = require('fs'), path = require('path');
const { JSDOM } = require('/Users/shunyu/projects/pet-agent-status/node_modules/jsdom');
const REPO = '/Users/shunyu/projects/pet-agent-status';
let fails = 0;
const ck = (n, c, e) => { console.log((c ? 'ok   ' : 'FAIL ') + n + (c ? '' : ' :: ' + e)); if (!c) fails++; };

const html = fs.readFileSync(path.join(REPO, 'panel/panel.html'), 'utf8');
const emitted = [];
const handlers = {};
const dom = new JSDOM(html, { runScripts: 'dangerously', beforeParse(w) {
  w.pet = { events: { emit: (n, p) => emitted.push([n, p]), on: (n, f) => { handlers[n] = f; } } };
}});
const d = dom.window.document;

const btn = d.getElementById('install-codex');
ck('Codex 入口是 <button> 元素', btn && btn.tagName === 'BUTTON', btn && btn.tagName);
ck('Codex 按钮文案不是「即将支持」', btn && !/即将支持|coming soon/i.test(btn.textContent), btn && btn.textContent);
ck('Codex 按钮文案是接入意图', btn && /接入|Install/i.test(btn.textContent), btn && btn.textContent);
ck('Codex 按钮可见（非 hidden）', btn && !btn.hidden, String(btn && btn.hidden));

// 真实 DOM 点击事件（不是直调内部函数）
btn.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true }));
ck('点击发出 agent-status:install-codex 意图事件', emitted.some(e => e[0] === 'agent-status:install-codex'), JSON.stringify(emitted));

// 喂快照：codex 行徽标数据驱动
const snapH = handlers['agent-status:snapshot'];
ck('panel 订阅了 snapshot', typeof snapH === 'function', Object.keys(handlers).join(','));
snapH({ rows: [
  { sessionId: 'cx1', agent: 'codex', form: 'cli', project: 'demo', state: 'running', raw: 'running', subline: '运行中', timeText: '00:05', ts: 1, canJump: false },
  { sessionId: 'cl1', agent: 'claude-code', form: 'cli', project: 'demo2', state: 'waiting', raw: 'waiting', subline: '等待', timeText: '00:09', ts: 2, canJump: false }
], summary: { running: 1, waiting: 1, total: 2, unknown: 0 } });

const rows = d.querySelectorAll('.row, [class*="row"]');
const badges = d.querySelectorAll('.badge');
ck('渲染出 2 个徽标', badges.length === 2, String(badges.length) + ' rows=' + rows.length);
const cxBadge = [...badges].find(b => b.className.includes('is-codex'));
ck('codex 行徽标 class 为 is-codex（agent 字段驱动）', !!cxBadge, [...badges].map(b => b.className).join(' | '));
const clBadge = [...badges].find(b => b.className.includes('is-claude'));
ck('claude 行徽标 class 为 is-claude', !!clBadge, '');
ck('两个徽标 SVG path 不同（各自厂牌图形）', cxBadge && clBadge && cxBadge.querySelector('path').getAttribute('d') !== clBadge.querySelector('path').getAttribute('d'), '');
// waiting 置顶（DESIGN.md 排序，与 agent 无关）
const first = d.querySelector('.list, #list') ;
ck('waiting 行置顶（codex 存在不改变排序规则）', first && /waiting|等待/.test(first.children[0].textContent + first.children[0].className), first ? first.children[0].outerHTML.slice(0,200) : 'no list');

// 已接入态翻面
const instH = handlers['agent-status:install-state'];
if (typeof instH === 'function') {
  instH({ claude: false, codex: true });
  ck('codex 已接入 → 接入按钮隐藏', btn.hidden === true, String(btn.hidden));
  ck('codex 已接入 → 显示已接入 ✓', !d.getElementById('codex-installed').hidden, '');
  ck('codex 已接入 → 显示 Trust 提示（facts §hook trust）', !d.getElementById('codex-trust').hidden, '');
  ck('Trust 提示文案提到 Trust', /Trust/i.test(d.getElementById('codex-trust').textContent), d.getElementById('codex-trust').textContent);
  ck('claude 未接入 → claude 接入按钮仍在（两厂牌独立翻面）', !d.getElementById('install-claude') || !d.getElementById('install-claude').hidden, '');
} else { console.log('note: install-state handler 名不符，已注册:', Object.keys(handlers).join(',')); fails++; }

console.log(fails === 0 ? '\nPANEL: ALL PASS' : '\nPANEL: ' + fails + ' FAILED');
process.exit(fails ? 1 : 0);

